grid=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
cells={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==8}
pieces=[]
for r in range(3):
 for c in range(6):
  sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if sq<=cells: pieces.append(('sq',r,c,sq))
  footprint={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  for missing in footprint:
   tri=footprint-{missing}
   if tri<=cells: pieces.append(('L'+str((missing[0]-r,missing[1]-c)),r,c,tri))
# exact covers
sol=[]
def dfs(rem, chosen):
 if not rem:
  sol.append(chosen); return
 cell=min(rem)
 for p in pieces:
  if cell in p[3] and p[3]<=rem:
   dfs(rem-p[3],chosen+[p])
dfs(cells,[])
len(cells),len(pieces),len(sol), [[(p[0],p[1],p[2]) for p in s] for s in sol[:10]]
